/**
 * Creates a debounced function that delays invoking `func` until after `wait`
 * milliseconds have elapsed since the last time the debounced function was invoked.
 *
 * @template T - The return type of the original function.
 * @param {(...args: any[]) => T} func - The function to debounce.
 * @param {number} wait - The number of milliseconds to delay.
 * @param {boolean} [immediate=false] - If `true`, calls `func` on the leading edge
 *   instead of the trailing edge.
 * @returns {(...args: any[]) => T | undefined} A debounced function with a `cancel` method.
 */
function debounce(func, wait, immediate = false) {
  let timeoutId;

  /**
   * The debounced wrapper function.
   * @param {...any} args - Arguments to pass to the original function.
   * @returns {T | undefined} The result of `func` if called immediately, otherwise `undefined`.
   */
  const debounced = (...args) => {
    const callNow = immediate && !timeoutId;

    clearTimeout(timeoutId);

    timeoutId = setTimeout(() => {
      timeoutId = null;
      if (!immediate) {
        func(...args);
      }
    }, wait);

    if (callNow) {
      return func(...args);
    }

    return undefined;
  };

  /**
   * Cancels any pending debounced invocation.
   */
  debounced.cancel = () => {
    clearTimeout(timeoutId);
    timeoutId = null;
  };

  return debounced;
}

